 async function characterContext(user){const staff=await can(user,'direct')||await can(user,'moderate'),member=await participation.role(user,{staff});return {staff,participant:member.confirmed,audience:member.role==='spectator'&&!member.confirmed,nurse:await clinic.isNurse(user.id),owned:await shop.ownedCharacters(user),hasSelection:member.role==='spectator'&&!member.confirmed||!!await characterService.ownership(user.id)};}
