 async function survivalView(user,context){const ctx=await survivalContext(user,context?.team);return context?.kind==='chest'?survival.storage(user,context.team,ctx):context?.kind==='luggage'?survival.luggage(user,context.id,ctx):survival.snapshot(user,ctx);}
 async function refreshGear(c){const value=await survival.snapshot(c.user,{staff:c.direct});c.gear=value.personal;if(c.wellness){c.wellness.pajamasOwned=await shop.ownedPajamas(c.user);syncClothing(c.gear,c.wellness);}send(c,{type:'survival-personal',data:value});}
 async function radioContacts(c){if(!c)return [];const own=await survival.radio(c.user);if(!own.ready||!own.team)return [];const result=[];for(const other of clients.values()){if(other===c||other.wellness.life.status!=='alive')continue;const v=await survival.radio(other.user);if(v.ready&&v.team===own.team)result.push({id:other.user.id,name:other.user.name,zone:other.zone.id});}return result;}
