 async function ownWellness(user){const c=clientFor(user),b=c?.wellness||await healthStore.loadBody(user.id),pref=c?{characterId:c.characterId}:await preferences(user);applyCharacterHealthProfile(b,pref.characterId);b.pajamasOwned=await shop.ownedPajamas(user);const gear=c?.gear||(await survival.snapshot(user)).personal;syncClothing(gear,b);return wellnessSnapshot(b);}
 function sendWellness(c){if(c.gear)syncClothing(c.gear,c.wellness);const body=wellnessSnapshot(c.wellness),signature=JSON.stringify(body);if(signature!==c.lastWellnessWire){c.lastWellnessWire=signature;send(c,{type:'wellness',body,vitals:vitalView(c.vitals)});}}
 function nearHospital(user){const c=clientFor(user),map=WORLD_MAPS['hospital-interior'];return !!c&&c.zone.id===map.id&&map.props.some(p=>['medical-kit','medical-cabinet','medical-counter'].includes(p.type)&&Math.hypot(c.p.x-interactionPoint(map,p).x,c.p.y-interactionPoint(map,p).y)<=125);}
